    try:
        bdt=datetime.fromisoformat(b).date()
    except Exception:
        # try parse common formats
        try:
            bdt=datetime.strptime(b, '%Y-%m-%d').date()
        except Exception:
            continue
    if bdt.month==now_date.month and bdt.day==now_date.day:
        matches.append((c,btd:=bdt))

